*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:          #0f1117;
  --surface:     #1a1d27;
  --surface-2:   #22263a;
  --border:      #2e3350;
  --border-focus:#5b8dee;
  --text:        #e4e6f0;
  --text-muted:  #8b90a8;
  --accent:      #5b8dee;
  --accent-hover:#7aa3f4;
  --correct:     #3ecf8e;
  --incorrect:   #f45b69;
  --radius:      10px;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
}
.skip-link:focus { top: 1rem; }

/* ── Layout ── */
#main {
  max-width: 680px;
  margin: 0 auto;
}

.quiz-header {
  text-align: center;
  margin-bottom: 2.5rem;
}
.quiz-header h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #5b8dee, #a78bfa);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.quiz-header p {
  margin-top: 0.5rem;
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* ── Form ── */
.quiz-form { display: flex; flex-direction: column; gap: 1.5rem; }

/* ── form-field (question card) ── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  transition: border-color 0.2s;
}
.form-field:focus-within { border-color: var(--accent); }

/* fieldset/legend reset */
.form-field fieldset {
  border: none;
  padding: 0;
}
.form-field legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  padding: 0;
  margin-bottom: 0.5rem;
  width: 100%;
}
.question-number {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: 4px;
  padding: 0.15rem 0.45rem;
  margin-bottom: 0.5rem;
}

/* ── Help text ── */
.help-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 0.75rem;
}

/* ── Checkbox options ── */
.options { display: flex; flex-direction: column; gap: 0.5rem; margin-top: 0.75rem; }

.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  user-select: none;
}
.option:hover { background: var(--surface-2); border-color: var(--accent); }
.option input[type="checkbox"] {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: var(--accent);
  flex-shrink: 0;
  cursor: pointer;
}
.option input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}
.option-label {
  font-size: 0.95rem;
  cursor: pointer;
}

/* ── Answered states ── */
.form-field.answered .option.correct {
  border-color: var(--correct);
  background: rgba(62, 207, 142, 0.08);
}
.form-field.answered .option.incorrect {
  border-color: var(--incorrect);
  background: rgba(244, 91, 105, 0.08);
}
.form-field.answered .option.missed {
  border-color: var(--correct);
  background: rgba(62, 207, 142, 0.04);
  opacity: 0.75;
}
.answer-badge {
  margin-left: auto;
  font-size: 0.75rem;
  font-weight: 700;
  padding: 0.1rem 0.4rem;
  border-radius: 4px;
}
.option.correct .answer-badge   { color: var(--correct); }
.option.incorrect .answer-badge { color: var(--incorrect); }
.option.missed .answer-badge    { color: var(--correct); opacity: 0.8; }

/* ── Submit button ── */
.submit-btn {
  align-self: flex-end;
  padding: 0.75rem 2rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}
.submit-btn:hover  { background: var(--accent-hover); }
.submit-btn:active { transform: scale(0.97); }
.submit-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}
.submit-btn:disabled {
  background: var(--border);
  cursor: not-allowed;
  transform: none;
}

/* ── Results banner ── */
.results-banner {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  text-align: center;
}
.results-banner h2 { font-size: 1.4rem; margin-bottom: 0.5rem; }
.results-banner p  { color: var(--text-muted); font-size: 0.95rem; }
.score-big {
  font-size: 3rem;
  font-weight: 800;
  background: linear-gradient(135deg, #5b8dee, #a78bfa);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  line-height: 1;
  margin: 0.75rem 0;
}

/* ── Live region ── */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Forced Colors ── */
@media (forced-colors: active) {
  .option { border: 2px solid ButtonText; }
  .option:hover,
  .form-field.answered .option.correct,
  .form-field.answered .option.incorrect,
  .form-field.answered .option.missed { border-color: Highlight; }
  .submit-btn { forced-color-adjust: none; }
  .quiz-header h1, .score-big { -webkit-text-fill-color: unset; background: none; color: ButtonText; }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow (320 px) ── */
@media (max-width: 360px) {
  .form-field { padding: 1rem; }
  .submit-btn { width: 100%; align-self: stretch; }
}
