 *
 * React-style component structure rendered to a single standalone HTML document.
 * Components: App → QuizHeader, QuizForm → QuestionCard, ResultsBanner
 */

// ── Data ────────────────────────────────────────────────────────────────────

const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1",
    text: "Which of the following are statically typed programming languages?",
    helpText: "Select all that apply. A language is statically typed if types are checked at compile time.",
    options: [
      { id: "q1-a", value: "java",       label: "Java" },
      { id: "q1-b", value: "python",     label: "Python" },
      { id: "q1-c", value: "typescript", label: "TypeScript" },
      { id: "q1-d", value: "rust",       label: "Rust" },
    ],
    correctValues: ["java", "typescript", "rust"],
  },
  {
    id: "q2",
    number: "Question 2",
    text: "Which languages were primarily designed for systems programming?",
    helpText: null,
    options: [
      { id: "q2-a", value: "c",      label: "C" },
      { id: "q2-b", value: "ruby",   label: "Ruby" },
      { id: "q2-c", value: "cpp",    label: "C++" },
      { id: "q2-d", value: "rust2",  label: "Rust" },
    ],
    correctValues: ["c", "cpp", "rust2"],
  },
  {
    id: "q3",
    number: "Question 3",
    text: "Which of the following languages support first-class functions?",
    helpText: null,
    options: [
      { id: "q3-a", value: "javascript", label: "JavaScript" },
      { id: "q3-b", value: "haskell",    label: "Haskell" },
      { id: "q3-c", value: "cobol",      label: "COBOL" },
      { id: "q3-d", value: "python3",    label: "Python" },
    ],
    correctValues: ["javascript", "haskell", "python3"],
  },
];

// ── Utilities ────────────────────────────────────────────────────────────────

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, val] of Object.entries(attrs)) {
    if (key === "className") node.className = val;
