      node.setAttribute(attr, val);
    } else if (key in node) {
      node[key] = val;
    } else {
      node.setAttribute(key, val);
    }
  }
  for (const child of children.flat()) {
    if (child == null) continue;
    node.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
  }
  return node;
}

// ── Components ───────────────────────────────────────────────────────────────

function QuizHeader() {
  return el("header", { className: "quiz-header" },
    el("h1", {}, "Computer Languages Quiz"),
    el("p", {}, "Test your knowledge — select all correct answers for each question.")
  );
}

function OptionItem({ question, option, answered, isSelected, correctValues }) {
  const isCorrect   = correctValues.includes(option.value);
  const isIncorrect = answered && isSelected && !isCorrect;
  const isMissed    = answered && !isSelected && isCorrect;
  const isRight     = answered && isSelected && isCorrect;

  let optionClass = "option";
  let badgeText   = null;
  if (isRight)      { optionClass += " correct";   badgeText = "✓ Correct"; }
  if (isIncorrect)  { optionClass += " incorrect"; badgeText = "✗ Wrong"; }
  if (isMissed)     { optionClass += " missed";    badgeText = "Missed"; }

  const input = el("input", {
    type: "checkbox",
    id: option.id,
    name: question.id,
    value: option.value,
  });
  input.checked = isSelected;
  if (answered) input.disabled = true;

  const label = el("label", { htmlFor: option.id, className: "option-label" }, option.label);
  const children = [input, label];
  if (badgeText) {
    children.push(el("span", { className: "answer-badge", "aria-hidden": "true" }, badgeText));
  }

  return el("div", { className: optionClass }, ...children);
}

function QuestionCard({ question, state, answered, onToggle }) {
  const fieldsetAttrs = { className: "form-field" + (answered ? " answered" : "") };
  if (answered) fieldsetAttrs.id = question.id + "-card";

  const fieldset = el("fieldset",
    question.helpText
      ? { "aria-describedby": question.id + "-help" }
      : {},
  );

  const legendEl = el("legend", {},
    el("span", { className: "question-number", "aria-hidden": "true" }, question.number),
    el("br", {}),
    question.text
  );
  fieldset.appendChild(legendEl);

  if (question.helpText) {
    fieldset.appendChild(
      el("p", { id: question.id + "-help", className: "help-text" }, question.helpText)
    );
  }

  const optionList = el("div", { className: "options", role: "group" });
  for (const option of question.options) {
    const optionEl = OptionItem({
      question,
      option,
      answered,
      isSelected: state.has(option.value),
      correctValues: question.correctValues,
    });

    if (!answered) {
      optionEl.addEventListener("change", (e) => {
        if (e.target.type === "checkbox") onToggle(question.id, option.value);
      });
      // clicking the whole row also works via the label, but make row clickable too
      optionEl.addEventListener("click", (e) => {
        if (e.target.tagName !== "INPUT" && e.target.tagName !== "LABEL") {
          const cb = optionEl.querySelector("input");
          cb.click();
        }
      });
    }

    optionList.appendChild(optionEl);
  }
  fieldset.appendChild(optionList);

  const wrapper = el("div", { className: "form-field" + (answered ? " answered" : "") });
  wrapper.appendChild(fieldset);
  return wrapper;
}

function ResultsBanner({ score, total }) {
  const pct = Math.round((score / total) * 100);
  return el("div", { className: "results-banner", role: "region", "aria-label": "Quiz results" },
    el("h2", {}, "Quiz complete!"),
    el("div", { className: "score-big", "aria-label": `${score} out of ${total}` }, `${score}/${total}`),
    el("p", {}, `You scored ${pct}% — ${score === total ? "Perfect score! 🎉" : score >= total / 2 ? "Good effort! Keep learning." : "Review the answers and try again."}`),
  );
}

// ── App (stateful root) ──────────────────────────────────────────────────────

function App(container) {
  // State: map of questionId → Set of selected values
  const selections = {};
  for (const q of QUESTIONS) selections[q.id] = new Set();

  let submitted = false;
  let score = 0;

  function handleToggle(questionId, value) {
    if (submitted) return;
    const sel = selections[questionId];
    if (sel.has(value)) sel.delete(value);
    else sel.add(value);
    render();
  }

  function handleSubmit(e) {
    e.preventDefault();
    submitted = true;

    // Calculate score: full credit per question only if selections exactly match correct answers
    score = QUESTIONS.filter((q) => {
      const sel = selections[q.id];
      const correct = new Set(q.correctValues);
      return sel.size === correct.size && [...sel].every((v) => correct.has(v));
    }).length;

    render();

    // Announce result and move focus to results banner
    requestAnimationFrame(() => {
      const banner = document.getElementById("results-live");
      if (banner) banner.focus();
    });
  }

  function render() {
    container.innerHTML = "";

    const main = el("main", { id: "main", tabindex: "-1" });
    main.appendChild(QuizHeader());

    const form = el("form", {
      className: "quiz-form",
      novalidate: "",
    });
    form.setAttribute("novalidate", "");

    // Live region for results announcement
    const liveRegion = el("div", {
      "aria-live": "polite",
      "aria-atomic": "true",
      className: "sr-only",
      id: "quiz-status",
    });
