const fs = require('fs');
const path = require('path');

(async () => {
  const dir = process.env.QUIZ_DIR;
  // Build a self-contained HTML with inlined CSS/JS so we don't need a server
  const html    = fs.readFileSync(path.join(dir,'index.html'),'utf8');
  const css     = fs.readFileSync(path.join(dir,'styles.css'),'utf8');
  const js      = fs.readFileSync(path.join(dir,'quiz.js'),'utf8');

  const inlined = html
    .replace('<link rel=\"stylesheet\" href=\"styles.css\" />', '<style>' + css + '</style>')
    .replace('<script src=\"quiz.js\"></script>', '<script>' + js + '</script>');

  const b = await chromium.launch();
  const page = await b.newPage();
  await page.setContent(inlined, { waitUntil: 'load' });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate('async () => await window.axe.run()');
  await b.close();

  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
  const out = {
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, nodes: v.nodes.map(n => ({ target: n.target, failureSummary: n.failureSummary })) })),
    bp:   bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) })),
  };
  process.stdout.write(JSON.stringify(out, null, 2));
  process.exitCode = wcag.length > 0 ? 1 : 0;
})();
